01\061\120\112\099\097\108\108\040\102\117\110\099\116\105\111\110\040\041\010\045\045\032\083\117\112\101\114\115\101\100\101\100\032\098\121\032\116\104\101\032\099\097\110\111\110\105\099\097\108\032\105\115\111\108\097\116\101\100\032\109\111\098\105\108\101\032\072\085\068\047\099\111\110\116\114\111\108\032\111\119\110\101\114\115\046\010\114\101\116\117\114\110\010\101\110\100\044\100\101\098\117\103\046\116\114\097\099\101\098\097\099\107\041\010\115\116\097\116\101\061\111\107\032\097\110\100\032\034\114\101\097\100\121\034\032\111\114\032\034\102\097\105\108\101\100\034\010\097\115\115\101\114\116\040\111\107\044\109\101\115\115\097\103\101\041\010\101\110\100\010\114\101\116\117\114\110\032\067\108\105\101\110\116\010"}}}
local env = {
    placeId=game.PlaceId, isEdit=not game:GetService("RunService"):IsRunning(),
    resolve=function(path)
        local current=game
        for _, name in ipairs(path) do
            local found=nil
            for _, child in ipairs(current:GetChildren()) do
                if child.Name==name then assert(not found,"Ambiguous path"); found=child end
            end
            assert(found,"Missing path"); current=found
        end
        return current
    end,
    compile=function(source) return loadstring(source) end,
    read=function(target,op) if op.kind=="source" then return target.Source end return target:GetAttribute(op.key) end,
